head.script:
scwin.trigger1_onclick = function(e) {
    // validate Ctrl + C
    isCopyValid = input1.validator.validateKeyPress(input1, input1.getValue(), {
        metaKey: true,
        charCode: 67
    });
};
scwin.trigger4_onclick = function(e) {
    // validate Ctrl + V
    isPasteValid = input1.validator.validateKeyPress(input1, input1.getValue(), {
        metaKey: true,
        charCode: 86
    });
};
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('123')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("assert", "isCopyValid", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("assert", "isPasteValid", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.isCopyValid = false;
    window.isPasteValid = false;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
